<template>
  <section class="recipe-page">
    <header class="recipe-heading">
      <div><nav><RouterLink to="/dashboard/cost-control/products">محصولات</RouterLink><span>/</span><strong>دستور تولید</strong></nav><h2>{{product?.name||'دستور تولید محصول'}}</h2><p v-if="product">ترکیب مواد و مقدار مصرف برای تولید یک واحد {{product.name}}</p></div>
      <AppBackButton class="back-button" fallback="/dashboard/cost-control/products" label="بازگشت به محصولات" />
    </header>

    <div v-if="loading" class="page-state"><i></i><span>در حال دریافت دستور تولید…</span></div>
    <div v-else-if="loadError" class="page-state error" role="alert"><strong>دستور تولید دریافت نشد</strong><span>{{loadError}}</span><button @click="load">تلاش مجدد</button></div>
    <template v-else-if="product">
      <section class="product-summary">
        <div class="product-identity"><img v-if="product.image_url" :src="product.image_url" :alt="product.name"/><div><span>محصول</span><strong>{{product.name}}</strong><small>{{product.category_name}} · قیمت فروش {{money(product.price)}}</small></div></div>
        <article><span>مواد اولیه</span><strong>{{money(product.material_cost)}}</strong></article><article><span>بسته‌بندی</span><strong>{{money(product.packaging_cost)}}</strong></article><article><span>ضایعات</span><strong>{{money(product.waste_cost)}}</strong></article><article><span>سربار تخصیص‌یافته</span><strong>{{money(product.allocated_overhead_cost)}}</strong></article><article class="total-cost"><span>بهای تمام‌شده</span><strong>{{money(product.final_production_cost)}}</strong></article>
      </section>

      <div v-if="hasMissingPrices" class="missing-price" role="status">برای یک یا چند ماده قیمت قابل استفاده ثبت نشده است؛ هزینه نمایش‌داده‌شده آن ردیف‌ها صفر است.</div>

      <div class="recipe-layout">
        <form class="ingredient-form" novalidate @submit.prevent="save">
          <header><div><h3>{{editingLine?'ویرایش ماده مصرفی':'افزودن ماده به دستور تولید'}}</h3><p>مقدار مصرف برای تولید یک واحد محصول را وارد کنید.</p></div></header>
          <div v-if="formError" class="form-error" role="alert">{{formError}}</div>
          <label><span>ماده اولیه <b>الزامی</b></span><select v-model="form.ingredient" :disabled="Boolean(editingLine)||saving" required><option disabled value="">انتخاب ماده اولیه</option><option v-for="ingredient in availableIngredients" :key="ingredient.id" :value="ingredient.id">{{ingredient.name}} — {{ingredient.category_name?`${ingredient.category_name} · `:''}}{{ingredient.unit_display}}</option></select><small v-if="editingLine">برای تغییر ماده، این ردیف را حذف و ماده جدید اضافه کنید.</small><em v-if="fieldErrors.ingredient">{{firstError(fieldErrors.ingredient)}}</em></label>
          <label><span>نوع هزینه <b>الزامی</b></span><select v-model="form.cost_kind" :disabled="saving"><option value="material">مواد اولیه</option><option value="packaging">بسته‌بندی</option><option value="waste">ضایعات</option></select><em v-if="fieldErrors.cost_kind">{{firstError(fieldErrors.cost_kind)}}</em></label>
          <label><span>مقدار مصرف <b>الزامی</b></span><div class="quantity-input"><input v-model="form.quantity" type="number" min="0.001" step="0.001" inputmode="decimal" placeholder="۰" :disabled="saving" required/><i>{{selectedIngredient?.unit_display||'واحد'}}</i></div><small v-if="selectedIngredient && selectedIngredientCost>0">مبنای فعلی هر {{selectedIngredient.unit_display}}: {{money(selectedIngredientCost)}} ({{costSourceLabel(selectedIngredient.cost_source)}})</small><small v-else-if="selectedIngredient" class="missing">قیمت قابل استفاده برای این ماده ثبت نشده است.</small><em v-if="fieldErrors.quantity">{{firstError(fieldErrors.quantity)}}</em></label>
          <div v-if="estimatedLineCost" class="estimated-cost"><span>هزینه این مقدار</span><strong>{{money(estimatedLineCost)}}</strong></div>
          <footer><button type="submit" class="primary" :disabled="saving">{{saving?'در حال ذخیره…':editingLine?'ذخیره تغییرات':'افزودن به دستور تولید'}}</button><button v-if="editingLine" type="button" class="secondary" :disabled="saving" @click="resetForm">انصراف</button></footer>
        </form>

        <section class="composition">
          <header><div><h3>ترکیب کامل تولید</h3><p>{{number(lines.length)}} ماده برای تولید یک واحد {{product.name}}</p></div><strong>{{money(recipeTotal)}}</strong></header>
          <div v-if="!lines.length" class="empty-composition"><strong>دستور تولید هنوز خالی است</strong><span>اولین ماده اولیه و مقدار مصرف آن را اضافه کنید.</span></div>
          <div v-else class="composition-list"><article v-for="line in lines" :key="line.id"><div class="line-name"><strong>{{line.ingredient_name}}</strong><span class="kind">{{line.cost_kind_display}}</span></div><div><span>مقدار مصرف</span><strong>{{number(line.quantity)}} {{line.unit_display}}</strong></div><div><span>قیمت هر واحد</span><strong>{{Number(line.unit_price)>0?money(line.unit_price):'ثبت نشده'}}</strong><small>{{costSourceLabel(line.cost_source)}}</small></div><div><span>هزینه</span><strong>{{money(line.line_cost)}}</strong></div><footer><button class="edit" :disabled="saving||deletingId===line.id" @click="edit(line)">ویرایش</button><button class="delete" :disabled="saving||deletingId===line.id" @click="remove(line)">{{deletingId===line.id?'در حال حذف…':'حذف'}}</button></footer></article></div>
        </section>
      </div>
    </template>
  </section>
</template>

<script setup>
import { computed,onMounted,reactive,ref } from 'vue'
import { useRoute } from 'vue-router'
import AppBackButton from '@/components/common/AppBackButton.vue'
import API from '@/api/product-cost.api.js'
import { costErrorMessage,formatCostNumber as number,formatMoney as money } from '@/utils/costControl'
import { costSourceLabel, effectiveIngredientCost } from '@/utils/ingredientCost'

const route=useRoute(),product=ref(null),ingredients=ref([]),lines=ref([]),loading=ref(true),saving=ref(false),deletingId=ref(null),loadError=ref(''),formError=ref(''),fieldErrors=ref({}),editingLine=ref(null)
const form=reactive({ingredient:'',quantity:'',cost_kind:'material'})
const selectedIngredient=computed(()=>ingredients.value.find(item=>String(item.id)===String(form.ingredient))),availableIngredients=computed(()=>ingredients.value.filter(item=>editingLine.value||!lines.value.some(line=>String(line.ingredient)===String(item.id)))),selectedIngredientCost=computed(()=>selectedIngredient.value?.effective_cost??effectiveIngredientCost(selectedIngredient.value)),estimatedLineCost=computed(()=>Number(form.quantity||0)*selectedIngredientCost.value),recipeTotal=computed(()=>lines.value.reduce((sum,line)=>sum+Number(line.line_cost||0),0)),hasMissingPrices=computed(()=>lines.value.some(line=>Number(line.unit_price||0)<=0))
async function load(){loading.value=true;loadError.value='';try{const [productData,recipeData,ingredientData]=await Promise.all([API.product(route.params.productId),API.recipes(route.params.productId),API.activeIngredients()]);product.value=productData;lines.value=recipeData||[];ingredients.value=ingredientData}catch(cause){loadError.value=costErrorMessage(cause)}finally{loading.value=false}}
async function refreshRecipe(){const [productData,recipeData]=await Promise.all([API.product(route.params.productId),API.recipes(route.params.productId)]);product.value=productData;lines.value=recipeData||[]}
const firstError=value=>Array.isArray(value)?value[0]:value
function resetForm(){editingLine.value=null;formError.value='';fieldErrors.value={};Object.assign(form,{ingredient:'',quantity:'',cost_kind:'material'})}
function edit(line){editingLine.value=line;formError.value='';fieldErrors.value={};Object.assign(form,{ingredient:line.ingredient,quantity:line.quantity,cost_kind:line.cost_kind});window.scrollTo({top:0,behavior:'smooth'})}
async function save(){formError.value='';fieldErrors.value={};if(!form.ingredient){fieldErrors.value={ingredient:'ماده اولیه را انتخاب کنید.'};return}if(!form.quantity||Number(form.quantity)<=0){fieldErrors.value={quantity:'مقدار مصرف باید بزرگ‌تر از صفر باشد.'};return}saving.value=true;try{await API.saveRecipe(route.params.productId,{ingredient:form.ingredient,quantity:Number(form.quantity),cost_kind:form.cost_kind});await refreshRecipe();resetForm()}catch(cause){formError.value=costErrorMessage(cause);fieldErrors.value=cause.cost?.errors||{}}finally{saving.value=false}}
async function remove(line){if(!confirm(`ماده «${line.ingredient_name}» از دستور تولید حذف شود؟`))return;deletingId.value=line.id;formError.value='';try{await API.removeRecipe(route.params.productId,line.id);if(editingLine.value?.id===line.id)resetForm();await refreshRecipe()}catch(cause){formError.value=costErrorMessage(cause)}finally{deletingId.value=null}}
onMounted(load)
</script>

<style scoped>
