8rem}.ingredient-form header p,.composition header p{margin:4px 0 0;color:var(--muted);font-size:.72rem}.ingredient-form label{display:grid;gap:6px;font-size:.78rem;font-weight:700}.ingredient-form label>span b{color:var(--muted);font-size:.64rem;font-weight:400}.ingredient-form input,.ingredient-form select{width:100%;min-height:43px;padding:9px 10px;border:1px solid var(--border-strong);border-radius:9px;background:var(--input);color:var(--text);font:inherit}.ingredient-form input:focus,.ingredient-form select:focus{outline:3px solid var(--focus);border-color:var(--primary)}.ingredient-form label small{color:var(--muted);font-size:.65rem;font-weight:400}.ingredient-form label small.missing{color:var(--danger)}.ingredient-form label em{color:var(--danger);font-size:.7rem;font-style:normal}.quantity-input{position:relative}.quantity-input input{padding-left:65px}.quantity-input i{position:absolute;left:10px;top:50%;transform:translateY(-50%);color:var(--muted);font-size:.66rem;font-style:normal}.estimated-cost{display:flex;justify-content:space-between;padding:11px;background:var(--surface-subtle);border-radius:9px;font-size:.76rem}.ingredient-form footer{display:flex;gap:8px}.primary{flex:1;padding:10px 13px;border:0;border-radius:9px;background:var(--primary);color:#fff;font:inherit;font-weight:700;cursor:pointer}button:disabled{opacity:.55;cursor:not-allowed}.form-error{padding:10px;border:1px solid #fecaca;border-radius:9px;background:#fef2f2;color:var(--danger);font-size:.72rem}.composition{overflow:hidden}.composition>header{display:flex;align-items:flex-start;justify-content:space-between;gap:12px;padding:16px;border-bottom:1px solid var(--border)}.composition>header>strong{color:var(--primary)}.composition-list article{display:grid;grid-template-columns:minmax(150px,1.3fr) repeat(3,minmax(100px,1fr)) auto;align-items:center;gap:14px;padding:14px 16px;border-bottom:1px solid var(--border)}.composition-list article:last-child{border-bottom:0}.composition-list article>div{display:grid;gap:4px}.composition-list article>div>span,.composition-list article>div>small{color:var(--muted);font-size:.67rem}.composition-list article>div>strong{font-size:.78rem}.line-name{display:flex!important;align-items:center;flex-direction:row;flex-wrap:wrap}.line-name>strong{font-size:.82rem!important}.kind{padding:3px 7px;border-radius:99px;background:var(--surface-subtle);color:var(--primary)!important}.composition-list footer{display:flex;gap:5px}.composition-list button{padding:6px;border:0;background:transparent;font:inherit;font-size:.7rem;cursor:pointer}.composition-list .edit{color:var(--primary)}.composition-list .delete{color:var(--danger)}.empty-composition,.page-state{min-height:240px;display:grid;place-content:center;justify-items:center;gap:7px;padding:24px;color:var(--muted);text-align:center;font-size:.78rem}.page-state i{width:30px;height:30px;border:3px solid var(--border);border-top-color:var(--primary);border-radius:50%;animation:spin .7s linear infinite}.page-state.error{color:var(--danger)}.page-state button{border:0;background:transparent;color:inherit;text-decoration:underline;cursor:pointer}@keyframes spin{to{transform:rotate(360deg)}}@media(max-width:1250px){.product-summary{grid-template-columns:repeat(3,minmax(0,1fr))}.product-identity{grid-column:span 2}}@media(max-width:1100px){.product-summary{grid-template-columns:repeat(2,minmax(0,1fr))}.product-identity{grid-column:1/-1}.recipe-layout{grid-template-columns:1fr}.ingredient-form{position:static}.composition-list article{grid-template-columns:repeat(2,minmax(0,1fr))}.composition-list footer{justify-self:end}}@media(max-width:640px){.recipe-heading{display:grid}.back-button{justify-self:start}.product-summary{grid-template-columns:1fr}.product-identity{grid-column:auto}.composition-list article{grid-template-columns:1fr}.composition-list footer{justify-self:start}.ingredient-form footer{flex-direction:column}}
</style>
